let toastTimer, refreshPromise;
function node(tag, className, text) { const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=String(text);return n; }
function text(id,value) {const n=$(id);if(n&&n.textContent!==String(value))n.textContent=String(value);}
function json(value){return JSON.stringify(value,null,2);}
function date(value){return value&&!Number.isNaN(Date.parse(value))?dateFormatter.format(new Date(value)):'—';}
function bytes(n){return n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`;}
function currentProject(){return state.data?.services?.projects?.current??{id:'primary',name:'当前工作区',path:state.data?.config?.workspace};}
function serviceState(name){return state.data?.services?.[name];}
function hasIdentityConfiguration(){return Boolean(serviceState('identity'))||(state.data?.plugins??[]).some(plugin=>plugin.id==='identity');}
function tools(){return state.data?.tools??[];}
function hasTool(name){return tools().some(t=>t.name===name);}
function taskTitle(t){return toolTitles[t.tool]??tools().find(x=>x.name===t.tool)?.title??t.tool??'任务';}
function badge(status){return node('span',`badge status-${String(status).replace(/[^a-z_]/g,'')}`,labels[status]??status??'未知');}
function empty(title,description,symbol='≋'){const n=node('div','empty-state');n.append(node('span','empty-symbol',symbol),node('h3','',title));if(description)n.append(node('p','',description));return n;}
function notify(message,error=false){clearTimeout(toastTimer);text('toast',message);$('toast').classList.toggle('error',error);$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,error?8000:4000);}
function button(title,fn,style='',key){const b=node('button',`button ${style}`,title);b.type='button';if(key)b.dataset.control=key;b.addEventListener('click',()=>void perform(b,fn));return b;}
async function perform(control,fn){if(control?.disabled)return;const old=control?.textContent;if(control){control.disabled=true;control.textContent='处理中…';}try{return await fn();}catch(error){notify(error.message||'操作未完成，请重试。',true);}finally{if(control?.isConnected){control.disabled=false;control.textContent=old;}}}
async function api(path,body,timeout=20000){const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'X-Capyra-Local':'1',...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:AbortSignal.timeout(timeout)});let result;try{result=await response.json();}catch{throw new Error('本机服务返回了无法读取的响应。请刷新或检查运行日志。');}if(!response.ok){const error=new Error(result.error||`操作未完成（${response.status}）`);error.status=response.status;throw error;}return result;}
async function service(name,method,args={}){const result=await api(`/api/services/${encodeURIComponent(name)}/${encodeURIComponent(method)}`,args,120000);return result?.result??result;}
async function mutation(path,body,message){const result=await api(path,body);if(message)notify(message);await refresh();return result;}
function rawDisclosure(title,value){const d=node('details','disclosure disclosure-raw');d.append(node('summary','',title),node('pre','code-block',typeof value==='string'?value:json(value)));return d;}
// 轮询只替换发生变化的区域，并保留展开项和键盘焦点；编辑器内容不会被轮询覆盖。
function stableRender(id,signature,build){const old=$(id);if(!old||old.dataset.signature===signature)return;const active=old.contains(document.activeElement)?document.activeElement?.dataset.control:undefined;const opened=[...old.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent);const values=new Map([...old.querySelectorAll('select[data-control]')].map(n=>[n.dataset.control,n.value]));const children=build();old.replaceChildren(...(Array.isArray(children)?children:[children]));old.dataset.signature=signature;for(const d of old.querySelectorAll('details'))if(opened.includes(d.querySelector('summary')?.textContent))d.open=true;for(const n of old.querySelectorAll('select[data-control]'))if(values.has(n.dataset.control))n.value=values.get(n.dataset.control);if(active)old.querySelector(`[data-control="${CSS.escape(active)}"]`)?.focus({preventScroll:true});}
function updateOptions(id,items,selected,placeholder){const select=$(id);const signature=json(items);if(select.dataset.signature!==signature){const previous=select.value;select.replaceChildren();if(placeholder){const option=node('option','',placeholder);option.value='';select.append(option);}for(const item of items){const option=node('option','',item.label);option.value=item.value;option.disabled=item.disabled===true;select.append(option);}select.dataset.signature=signature;select.value=selected??previous;if(![...select.options].some(option=>option.value===select.value))select.value=placeholder?'':items[0]?.value??'';}else if(selected!==undefined&&select.value!==selected)select.value=selected;}
function decodedResult(task){const result=task?.result;if(result?.structuredContent)return result.structuredContent;const texts=result?.content?.filter(c=>c.type==='text')??[];if(texts.length===1){try{return JSON.parse(texts[0].text);}catch{return texts[0].text;}}return texts.length?texts.map(c=>c.text).join('\n\n'):result;}
async function detail(id){const item=await api(`/api/tasks/${encodeURIComponent(id)}`);state.details.set(id,item);while(state.details.size>20)state.details.delete(state.details.keys().next().value);return item;}
async function submitTool(name,args={},options={}){if(!hasTool(name))throw new Error(`能力「${toolTitles[name]??name}」当前未启用，请在插件组合中启用对应插件。`);return followSubmittedTask(await api('/api/tools/call',{name,args}),options);}
async function submitAgentAction(method,args){return followSubmittedTask(await service('agents',method,args));}
async function followSubmittedTask(response,options={}){let task=response.task??response;const id=task.id??response.taskId;if(!id)throw new Error('工具提交后未返回任务 ID。请在任务记录中核对。');if(!task.status)task=await detail(id);if(task.status==='awaiting_approval'&&!options.quiet)await openTask(id);if(!activeStatuses.has(task.status)){if(task.status!=='succeeded')throw new Error(task.error??labels[task.status]??'任务未完成');if(!task.result)task=await detail(id);return options.raw?task.result:decodedResult(task);}return new Promise((resolve,reject)=>{state.watchers.set(id,{resolve,reject,raw:options.raw,quiet:options.quiet,opened:task.status==='awaiting_approval'});void refresh();});}
async function checkWatchers(){for(const [id,watcher]of state.watchers){const summary=state.data?.tasks?.find(t=>t.id===id);if(!summary)continue;if(summary.status==='awaiting_approval'&&!watcher.quiet&&!watcher.opened){watcher.opened=true;void openTask(id);}if(activeStatuses.has(summary.status))continue;state.watchers.delete(id);try{const task=await detail(id);if(task.status==='succeeded')watcher.resolve(watcher.raw?task.result:decodedResult(task));else watcher.reject(new Error(task.error??`操作${labels[task.status]??task.status}`));}catch(error){watcher.reject(error);}}}
async function refresh(){if(refreshPromise)return refreshPromise;refreshPromise=(async()=>{try{state.data=await api('/api/state');state.online=true;state.authRequired=false;$('entry-gate').hidden=true;for(const section of document.querySelectorAll('.page'))section.hidden=section.id!==state.page;$('connection-error').hidden=true;$('service-dot').classList.remove('offline');text('service-status','本机服务运行中');text('updated-label','与本机同步');render();await checkWatchers();if(state.selectedTask&&state.dialogKind==='task'&&$('detail-dialog').open){const summary=state.data.tasks?.find(t=>t.id===state.selectedTask);if(summary?.updatedAt!==state.details.get(state.selectedTask)?.updatedAt){await detail(state.selectedTask);renderTaskDetail();}}}catch(error){state.online=false;state.authRequired=error.status===401;$('entry-gate').hidden=!state.authRequired;if(state.authRequired)for(const section of document.querySelectorAll('.page'))section.hidden=true;$('connection-error').hidden=state.authRequired;text('connection-error','暂时无法连接本机服务。请确认 Capyra 正在运行；恢复后会自动同步。');text('service-status',state.authRequired?'等待浏览器配对':'连接已中断');$('service-dot').classList.add('offline');text('updated-label',state.data?'显示上次同步记录':'等待本机服务');$('pause-button').disabled=true;}})();try{await refreshPromise;}finally{refreshPromise=null;}}
let confirmationFocus = null;
function openDialog(title,content,kind='custom'){confirmationFocus=null;$('detail-dialog').removeAttribute('aria-describedby');state.dialogKind=kind;if(kind!=='agent')state.agentView=null;if(kind!=='task')state.selectedTask=null;text('dialog-title',title);text('dialog-eyebrow',kind==='task'?'TASK DETAILS':'YOUR LOCAL WORKSPACE');$('dialog-body').replaceChildren(content);delete $('dialog-body').dataset.signature;if(!$('detail-dialog').open)$('detail-dialog').showModal();}
function closeDialog(){const returnFocus=confirmationFocus;confirmationFocus=null;state.agentView=null;state.selectedTask=null;state.dialogKind='';$('detail-dialog').close();$('dialog-body').replaceChildren();if(returnFocus)requestAnimationFrame(()=>{if($('detail-dialog').open)return;const target=returnFocus.isConnected&&!returnFocus.disabled?returnFocus:document.querySelector(`[data-nav="${state.page}"]`);target?.focus();});}
function confirmAction(title, description, confirmLabel, action, trigger) {
  const content = node('div'), message = node('p', 'muted', description), actions = node('div', 'actions wrap');
  message.id = 'confirmation-description';
  let decided = false;
  const cancel = button('取消', closeDialog);
  const confirm = button(confirmLabel, async () => {
    // 弹窗被关闭或被其他详情替换后，迟到的点击不能执行原操作。
    if (decided || state.dialogKind !== 'confirm' || !content.isConnected) return;
    decided = true;
    closeDialog();
    await action();
  }, 'danger');
  actions.append(cancel, confirm);
  content.append(message, actions);
  openDialog(title, content, 'confirm');
  confirmationFocus = trigger;
  $('detail-dialog').setAttribute('aria-describedby', message.id);
  // 默认落在取消；Enter 只执行当前聚焦按钮，Escape 使用同一关闭流程。
  cancel.focus();
}
function confirmationButton(title, description, confirmLabel, action, style = 'danger') {
  const trigger = button(title, () => confirmAction(title, description, confirmLabel, action, trigger), style);
  return trigger;
}
async function openTask(id){state.selectedTask=id;openDialog('任务详情',empty('正在读取任务详情','加载准确参数、预览与实际结果。'),'task');try{await detail(id);if(state.selectedTask===id)renderTaskDetail();}catch(error){$('dialog-body').replaceChildren(empty('暂时无法读取详情',error.message));}}
function taskRow(task){const b=node('button','task-row');b.type='button';b.dataset.control=`task-${task.id}`;b.setAttribute('aria-label',`${taskTitle(task)}，${labels[task.status]??task.status}，查看详情`);const copy=node('span','task-copy');copy.append(node('strong','',taskTitle(task)),node('small','',`${date(task.createdAt)} · ${task.workspace?task.workspace.split('/').filter(Boolean).pop():task.pluginId??'本机'}`));b.append(node('span','task-icon',task.effect==='execute'?'›_':task.effect==='write'?'↗':'⌕'),copy,badge(task.status),node('span','row-arrow','→'));b.onclick=()=>void openTask(task.id);return b;}
function visibilitySelect(id){const wrapper=node('div','visibility-control'),copy=node('div');copy.append(node('strong','','结果去向'),node('p','','敏感内容建议只在本机查看。'));const select=node('select');select.dataset.control=`visibility-${id}`;select.setAttribute('aria-label','本次请求的结果去向');for(const [value,label]of[['local','仅在本机查看'],['client','返回客户端 / ChatGPT']]){const option=node('option','',label);option.value=value;select.append(option);}wrapper.append(copy,select);return {wrapper,select};}
function previewView(task){const n=node('div','preview-content');if(!task.preview)return n;n.append(node('h3','',task.preview.title??'操作预览'),node('p','',task.preview.description??''));if(task.preview.before!==undefined||task.preview.after!==undefined){const sides=node('div','preview-comparison');for(const [field,title]of[['before','操作前'],['after','操作后']]){const side=node('div',`preview-side ${field}`);side.append(node('span','',title),node('pre','',task.preview[field]??''));sides.append(side);}n.append(sides);}return n;}
function approvalActions(task,container){const actions=node('div','actions wrap');if(task.status==='awaiting_approval'){const v=visibilitySelect(task.id);container.append(v.wrapper);actions.append(button('批准这次操作',async()=>{await mutation(`/api/tasks/${encodeURIComponent(task.id)}/approve`,{approve:true,resultVisibility:v.select.value},'已批准，任务将继续执行。');if(state.selectedTask===task.id){await detail(task.id);renderTaskDetail();}},'primary',`approve-${task.id}`),button('拒绝',()=>mutation(`/api/tasks/${encodeURIComponent(task.id)}/approve`,{approve:false},'已拒绝这次操作。'),'',`deny-${task.id}`));}else if(activeStatuses.has(task.status)){actions.append(button('取消任务',()=>mutation(`/api/tasks/${encodeURIComponent(task.id)}/cancel`,{},'已请求取消任务。'),'danger',`cancel-${task.id}`));}container.append(actions);}
function approvalCard(task){const card=node('article','card approval-card');const head=node('div','card-heading');head.append(node('h2','',taskTitle(task)),badge(task.status));const meta=node('div','detail-meta');meta.append(node('span','',`来源：${task.owner??'客户端'}`),node('span','',date(task.createdAt)));if(task.expiresAt)meta.append(node('span','',`到期 ${date(task.expiresAt)}`));card.append(head,meta,previewView(task));if(task.error)card.append(node('p','inline-error',task.error));approvalActions(task,card);card.append(button('查看完整参数',()=>openTask(task.id),'small',`detail-${task.id}`));return card;}
function accessCard(request){const card=node('article','card approval-card');const head=node('div','card-heading');head.append(node('h2','',request.description??request.method??request.operation??'读取请求'),badge(request.status??'pending'));card.append(head,node('div','detail-meta',`方法：${request.method??request.operation??'未知'} · 来源：${request.owner??'客户端'} · ${date(request.createdAt)} · 到期 ${date(request.expiresAt)}`),rawDisclosure('核对准确请求参数',{method:request.method??request.operation,args:request.args??{}}));const v=visibilitySelect(request.id);card.append(v.wrapper);const actions=node('div','actions wrap');actions.append(button('允许这次访问',()=>mutation(`/api/access/${encodeURIComponent(request.id)}/decide`,{approve:true,resultVisibility:v.select.value},'已允许这次请求。'),'primary',`access-${request.id}`),button('拒绝',()=>mutation(`/api/access/${encodeURIComponent(request.id)}/decide`,{approve:false},'已拒绝访问。'),'',`access-deny-${request.id}`));card.append(actions);return card;}
function oauthCard(auth){const card=node('article','card approval-card');const head=node('div','card-heading'),label=node('input');head.append(node('h2','','新的客户端连接'),badge('pending'));label.placeholder='例如：我的个人 ChatGPT';label.maxLength=80;label.autocomplete='off';card.append(head,node('p','progress-note',`${auth.clientName??'客户端'} · 验证码 ${auth.verificationCode??'未提供'}`),field('连接备注（可选）',label),rawDisclosure('核对连接信息',{client:auth.clientName,redirectUri:auth.redirectUri,createdAt:auth.createdAt}),node('p','form-note','ChatGPT 不提供登录邮箱；备注由你填写。连接授权后，每次文件访问、操作或历史结果查询仍按本机批准设置执行。'));const actions=node('div','actions');actions.append(button('允许连接',()=>mutation(`/api/oauth/${encodeURIComponent(auth.id)}/decide`,{approve:true,label:label.value.trim()||undefined},'已允许连接，请返回客户端完成授权。'),'primary',`oauth-${auth.id}`),button('拒绝',()=>mutation(`/api/oauth/${encodeURIComponent(auth.id)}/decide`,{approve:false},'已拒绝连接。'),'',`oauth-deny-${auth.id}`));card.append(actions);return card;}
function editGrantLabel(grant){const form=node('form','form-stack'),input=node('input'),submit=node('button','button primary','保存备注');input.value=grant.label??'';input.placeholder='例如：工作账号、个人账号';input.maxLength=80;input.autocomplete='off';submit.type='submit';form.append(field('连接备注',input),node('p','form-note','这是本机备注，用来区分连接；不是由 ChatGPT 验证的账号名称。'),submit);form.onsubmit=event=>{event.preventDefault();void perform(submit,async()=>{await mutation(`/api/oauth/${encodeURIComponent(grant.id)}/label`,{label:input.value.trim()||undefined},'连接备注已保存。');closeDialog();});};openDialog('命名 ChatGPT 连接',form);}
function grantCard(grant){const card=node('article','approval-card connection-grant'),head=node('div','card-heading'),title=grant.label??'未命名连接';head.append(node('h3','',title),badge(grant.status));card.append(head,node('p','progress-note',`${grant.clientName??'MCP 客户端'} · 连接 ${String(grant.id).slice(0,8)}`),node('p','form-note',grant.lastUsedAt?`最后访问 ${date(grant.lastUsedAt)} · 已验证 ${grant.requestCount??0} 次请求`:'尚未收到这条连接的 MCP 请求'),node('p','form-note',`授权到期 ${date(grant.expiresAt)}`));const actions=node('div','actions wrap');actions.append(button(grant.status==='paused'?'恢复访问':'暂停访问',()=>mutation(`/api/oauth/${encodeURIComponent(grant.id)}/pause`,{paused:grant.status!=='paused'},grant.status==='paused'?'这条连接已恢复访问。':'这条连接已暂停，正在进行的远程任务已中止。'),'small'),button('修改备注',()=>editGrantLabel(grant),'small'));const revoke=button('撤销连接',()=>confirmAction('撤销这条 ChatGPT 连接',`撤销“${title}”？这条连接需要重新完成 OAuth 才能再次访问。`,'确认撤销',()=>mutation(`/api/oauth/${encodeURIComponent(grant.id)}/revoke`,{},'这条连接已撤销。'),revoke),'small danger');actions.append(revoke);card.append(actions,rawDisclosure('连接技术信息',{clientName:grant.clientName,connectionId:grant.id,clientId:grant.clientId,status:grant.status,createdAt:grant.createdAt,lastUsedAt:grant.lastUsedAt,requestCount:grant.requestCount,expiresAt:grant.expiresAt,accountIdentity:'ChatGPT 未向 MCP 提供登录邮箱或 OpenAI 账号 ID'}));return card;}
function diffView(diff){const pre=node('pre','code-block diff-block');const lines=String(diff??'').split('\n');for(const line of lines){const kind=line.startsWith('+++')||line.startsWith('---')||line.startsWith('@@')||line.startsWith('diff ')?'meta':line.startsWith('+')?'add':line.startsWith('-')?'remove':'';pre.append(node('span',`diff-line ${kind}`,line||' '));}return pre;}
function table(headers,rows){const scroll=node('div','table-scroll'),t=node('table','data-table'),thead=node('thead'),tr=node('tr');for(const label of headers){const th=node('th','',label);th.scope='col';tr.append(th);}thead.append(tr);const body=node('tbody');for(const row of rows){const tr=node('tr');for(const value of row){const td=node('td');if(value instanceof Node)td.append(value);else td.textContent=String(value??'—');tr.append(td);}body.append(tr);}t.append(thead,body);scroll.append(t);return scroll;}
// 插件和文件内容只能成为文本；展示协议不会执行远程提供的 HTML 或 JavaScript。
