// 授权请求只短暂留在当前页面；重置或离开后，迟到响应也不能恢复敏感链接。
let localAuthorizationRevision = 0;
let localAuthorizationPending = 0;
let localAuthorizationTimer;
const localAuthorizationRetentionMs = 5 * 60 * 1000;
function trustedLocalAuthorizationUrl(value, mcpPort = state.data?.config?.port) {
  if (typeof value !== 'string') throw new Error('Invalid local authorization response');
  const url = new URL(value);
  if (url.protocol !== 'http:' || !['localhost', '127.0.0.1'].includes(url.hostname) || url.pathname !== '/authorize' || url.username || url.password || url.hash) {
    throw new Error('Invalid local authorization destination');
  }
  if (Number.isInteger(mcpPort) && mcpPort > 0 && Number(url.port || 80) !== mcpPort) throw new Error('Unexpected local authorization port');
  return url.href;
}
function renderLocalAuthorizationAvailability() {
  const unavailable = state.data?.connection?.localAuthorizationAvailable === false;
  $('local-authorization-unavailable').hidden = !unavailable;
  $('local-authorization-submit').disabled = unavailable || localAuthorizationPending !== 0;
  text('local-authorization-submit', localAuthorizationPending ? '正在准备…' : '准备本机授权入口');
}
function clearLocalAuthorization(clearInput = true) {
  localAuthorizationRevision++;
  localAuthorizationPending = 0;
  clearTimeout(localAuthorizationTimer);
  localAuthorizationTimer = undefined;
  if (clearInput) $('local-authorization-url').value = '';
  $('local-authorization-result').replaceChildren();
  $('local-authorization-result').hidden = true;
  text('local-authorization-error', '');
  $('local-authorization-error').hidden = true;
  renderLocalAuthorizationAvailability();
}
async function prepareLocalAuthorization() {
  const input = $('local-authorization-url').value.trim();
  clearLocalAuthorization(false);
  if (!input || state.data?.connection?.localAuthorizationAvailable === false) return;
  const revision = localAuthorizationRevision;
  localAuthorizationPending = revision;
  renderLocalAuthorizationAvailability();
  try {
    const result = await api('/api/oauth/local-authorize', { url: input });
    if (revision !== localAuthorizationRevision || !$('local-authorization-help').open) return;
    $('local-authorization-url').value = '';
    const href = trustedLocalAuthorizationUrl(result.localAuthorizeUrl);
    const link = node('a', 'button small primary', '在新页面继续授权 ↗');
    link.href = href;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.referrerPolicy = 'no-referrer';
    const output = $('local-authorization-result');
    output.replaceChildren(link, node('p', 'form-note', '打开后仍需在本机“待你确认”中核对授权，完成后回到 ChatGPT。此入口在本页保留 5 分钟。'));
    output.hidden = false;
    localAuthorizationTimer = setTimeout(() => {
      if (revision !== localAuthorizationRevision) return;
      clearLocalAuthorization();
      const output = $('local-authorization-result');
      output.replaceChildren(node('p', 'form-note', '链接已从本页清除。需要继续时，请重新复制本次最新的授权页面地址。'));
      output.hidden = false;
    }, localAuthorizationRetentionMs);
  } catch (error) {
    if (revision !== localAuthorizationRevision || !$('local-authorization-help').open) return;
    // 错误反馈不回显请求 URL，避免把授权参数带进通知或截图。
    text('local-authorization-error', error.status === 401 ? '本机管理会话已失效，请从 Capyra 启动入口重新打开控制台。' : error.status === 409 ? '当前连接尚未准备好。请先启动本机服务与公网连接，再准备本机授权入口。' : '本机授权入口未生成。请重新复制 ChatGPT 本次打开失败的完整授权地址，确认当前连接后重试。');
    $('local-authorization-error').hidden = false;
  } finally {
    if (localAuthorizationPending === revision) localAuthorizationPending = 0;
    renderLocalAuthorizationAvailability();
  }
}
function updateConnectionMode(){
  const select=$('connection-mode'),managed=$('connection-managed-option'),hasIdentity=Boolean(serviceState('identity'));
  managed.hidden=!hasIdentity;managed.disabled=!hasIdentity;
  if(!hasIdentity&&select.value==='managed')select.value='quick';
  const mode=select.value;
  $('connection-sites-fields').hidden=mode!=='sites';
  $('connection-managed-fields').hidden=mode!=='managed'||!hasIdentity;
  $('connection-named-fields').hidden=mode!=='named';
  $('connection-quick-note').hidden=mode!=='quick';
  $('connection-install').hidden=mode==='sites';
  text('connection-method-description',mode==='sites'?'本机主动连接 Sites，通过固定入口接收 ChatGPT 请求。':'Capyra 通过 Cloudflare Tunnel 将 ChatGPT 连接到本机 MCP。');
}
async function startConnection(){
  const mode=$('connection-mode').value;
  if(mode==='managed'&&!serviceState('identity'))throw new Error('请选择 Sites 固定连接、快速直连或自备 Named Tunnel。');
  $('connection-action-result').replaceChildren(node('p','progress-note',mode==='sites'?'正在建立 Sites 设备通道，请保持本机服务运行。':'正在准备连接，请保持本机服务运行。首次安装可能需要一些时间。'));
  try{
    if(mode==='managed')await service('connection','prepare');
    else{
      const args={mode:mode==='named'?'managed':mode,autoStart:true};
      if(mode==='sites'){
        args.sitesUrl=$('connection-sites-url').value.trim();
        if($('connection-enrollment-token').value)args.enrollmentToken=$('connection-enrollment-token').value;
      }
      if(mode==='named'){
        args.tunnelId=$('connection-tunnel-id').value.trim();args.publicUrl=$('connection-public-url').value.trim();
        if($('connection-token').value)args.token=$('connection-token').value;
      }
      await service('connection','configure',args);
      // Sites 使用本机主动连接，不依赖 cloudflared 的安装状态。
      if(mode!=='sites'&&!serviceState('connection')?.installation?.installed)await service('connection','install');
      await service('connection','start');
    }
    $('connection-token').value='';$('connection-enrollment-token').value='';connectionFormDirty=false;
    $('connection-action-result').replaceChildren(node('p','progress-note',mode==='sites'?'启动请求已完成。使用同一设备配置时，MCP 地址在重启后保持不变。首次使用请在 ChatGPT 添加连接并授权；实际工具调用状态单独显示在右侧。':'启动请求已完成。入口就绪后核对 MCP 地址：首次使用或地址变化时，在 ChatGPT 添加连接并授权；地址相同可继续使用。'));
    await refresh();
  }catch(error){$('connection-action-result').replaceChildren(node('p','inline-error',error.message));throw error;}
}
