for(const b of document.querySelectorAll('.close-dialog'))b.addEventListener('click',closeDialog);$('detail-dialog').addEventListener('cancel',event=>{event.preventDefault();closeDialog();});$('detail-dialog').addEventListener('click',e=>{if(e.target===$('detail-dialog')){const r=$('detail-dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});window.addEventListener('hashchange',navigate);window.addEventListener('beforeunload',e=>{if(state.file&&$('file-editor').value!==state.file.original){e.preventDefault();e.returnValue='';}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='s'&&state.page==='files'){e.preventDefault();if(!$('file-save').disabled)previewSave();}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!$('detail-dialog').open){e.preventDefault();location.hash='files';$('file-search').focus();}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)void refresh();});
async function boot(){let nonce;const match=location.hash.match(/^#bootstrap=([^&]+)$/);if(match){nonce=decodeURIComponent(match[1]);history.replaceState(null,'',location.pathname+location.search);try{await api('/api/bootstrap',{nonce});}catch(error){state.authRequired=true;$('entry-gate').hidden=false;notify('浏览器配对未完成。请从本机 Capyra 启动入口重新打开。',true);}finally{nonce=undefined;}}updateConnectionMode();navigate();await refresh();navigate();}void boot();setInterval(()=>{if(!document.hidden&&!state.authRequired)void refresh();},2000);setInterval(()=>{if(!document.hidden&&state.online&&state.page==='terminal')void readTerminal();},1800);

// 编辑中的选择不会被后台状态轮询覆盖，只有本机表单可提交此设置。
$('approval-settings-form').addEventListener('change',()=>{$('approval-settings-form').dataset.dirty='true';renderApprovalSettings();});
wire('approval-settings-form','submit',async()=>{await api('/api/approval-settings',{approvalMode:$('approval-mode').value,autoResultVisibility:$('auto-result-visibility').value});delete $('approval-settings-form').dataset.dirty;await refresh();notify('批准设置已保存，尚未开始的旧请求已取消。');});
